// Per-route metadata. The client is a SPA, so link-preview crawlers (Facebook, iMessage,
// Slack, X, LinkedIn) only ever see the HTML the server sends. server.js injects these tags
// into index.html for each route. `card` drives the share image generated by
// scripts/og-images.js -- rerun `npm run og` after changing it.
const SITE_URL = 'https://callforcivility.com';
const SITE_NAME = 'Call for Civility';

const DEFAULT_DESCRIPTION =
  'A Clarion Call for Civility. Join the movement for civility and honor in our nation and sign the Civility Pledge.';

const pages = {
  '/': {
    title: 'Call for Civility | A Clarion Call for Civility',
    ogTitle: 'A Clarion Call for Civility',
    description: DEFAULT_DESCRIPTION,
    image: 'home',
    card: {
      eyebrow: 'A national movement',
      heading: 'A Clarion Call for <em>Civility</em>',
      sub: 'Join the movement for civility and honor in our nation and sign the pledge.',
      background: 'hero-capitol.webp',
    },
  },
  '/pledge': {
    title: 'Pledge | Call for Civility',
    ogTitle: 'Sign the Civility Pledge',
    description:
      'Three commitments that can heal a house divided. Read the Civility Pledge, live it, and add your name to a growing movement for kindness and respect across America.',
    image: 'pledge',
    card: {
      eyebrow: 'Take the pledge',
      heading: 'Sign the Civility <em>Pledge</em>',
      sub: 'Three commitments that can heal a house divided.',
    },
  },
  '/letter-clarion-call-for-civility': {
    title: 'Letter | Call for Civility',
    ogTitle: 'An Open Letter: A Clarion Call for Civility',
    description:
      'An open letter to talk show hosts, news makers, and all media personnel calling for civility and respect in public life.',
    image: 'letter',
    type: 'article',
    card: {
      eyebrow: 'An open letter',
      heading: 'A Letter to <em>America’s Media</em>',
      sub: 'To talk show hosts, news makers, and all media personnel.',
    },
  },
  '/about-us': {
    title: 'About | Call for Civility',
    ogTitle: 'About Call for Civility',
    description:
      'Two lifelong public servants, one behind the microphone and one behind the badge, united by a call for civility.',
    image: 'about',
    card: {
      eyebrow: 'Who we are',
      heading: 'Meet the <em>Founders</em>',
      sub: 'One behind the microphone, one behind the badge, united by a call for civility.',
    },
  },
  '/video': {
    title: 'Video | Call for Civility',
    ogTitle: 'Call for Civility Videos',
    description:
      'Watch videos of events, including interviews with Sam Bushman, Richard Mack, and other Civility Advocates.',
    image: 'video',
    card: {
      eyebrow: 'Watch & share',
      heading: 'Voices for <em>Civility</em>',
      sub: 'Interviews with Sam Bushman, Richard Mack, and other civility advocates.',
    },
  },
  '/welcome': {
    title: 'Welcome | Call for Civility',
    ogTitle: 'Welcome to Call for Civility',
    description:
      'A word from our founder: America is divided over every fault line possible. Together, we can choose a better way.',
    image: 'welcome',
    card: {
      eyebrow: 'A word from our founder',
      heading: 'Together, a <em>Better Way</em>',
      sub: 'America is divided over every fault line possible. We can choose differently.',
      background: 'flag.webp',
    },
  },
  '/contact': {
    title: 'Contact | Call for Civility',
    ogTitle: 'Contact Call for Civility',
    description: 'Questions, speaking requests, or ways to volunteer: we would love to hear from you.',
    image: 'home',
  },
  '/accessibility': {
    title: 'Accessibility Statement | Call for Civility',
    ogTitle: 'Accessibility Statement',
    description: 'Our commitment to making Call for Civility usable by everyone.',
    image: 'home',
  },
};

const notFound = {
  title: 'Page not found | Call for Civility',
  ogTitle: 'Page not found',
  description: DEFAULT_DESCRIPTION,
  image: 'home',
  noindex: true,
};

// Plain-text heading of each share image, for its alt text.
const cardHeadings = Object.fromEntries(
  Object.values(pages)
    .filter((p) => p.card)
    .map((p) => [p.image, p.card.heading.replace(/<[^>]+>/g, '')])
);

const escape = (s) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Returns the <head> tags for a request path, plus whether the route exists.
function seoFor(pathname) {
  const route = pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname;
  const page = pages[route];
  const meta = page || notFound;
  const url = escape(SITE_URL + (page ? route : pathname));
  const image = `${SITE_URL}/img/og/${meta.image}.jpg`;
  const alt = `The Call for Civility seal beside the words “${cardHeadings[meta.image]}”`;

  const tags = [
    `<title>${escape(meta.title)}</title>`,
    `<meta name="description" content="${escape(meta.description)}" />`,
    meta.noindex ? '<meta name="robots" content="noindex" />' : `<link rel="canonical" href="${url}" />`,
    `<meta property="og:type" content="${meta.type || 'website'}" />`,
    `<meta property="og:site_name" content="${SITE_NAME}" />`,
    '<meta property="og:locale" content="en_US" />',
    `<meta property="og:title" content="${escape(meta.ogTitle)}" />`,
    `<meta property="og:description" content="${escape(meta.description)}" />`,
    `<meta property="og:url" content="${url}" />`,
    `<meta property="og:image" content="${image}" />`,
    '<meta property="og:image:type" content="image/jpeg" />',
    '<meta property="og:image:width" content="1200" />',
    '<meta property="og:image:height" content="630" />',
    `<meta property="og:image:alt" content="${escape(alt)}" />`,
    '<meta name="twitter:card" content="summary_large_image" />',
    `<meta name="twitter:title" content="${escape(meta.ogTitle)}" />`,
    `<meta name="twitter:description" content="${escape(meta.description)}" />`,
    `<meta name="twitter:image" content="${image}" />`,
    `<meta name="twitter:image:alt" content="${escape(alt)}" />`,
  ];

  return { found: Boolean(page), html: tags.join('\n    ') };
}

module.exports = { pages, seoFor, SITE_URL };
